/** Decode percent-encoded dots in keys case-insensitively. A check that is not the qs parser is refused. */
export function decodeDotKeysCaseInsensitively(source: string): string | null {
  if (!source.includes("options.decodeDotInKeys ? cleanRoot.replace(/%2E/g, '.')")) return null;
  return source === QS_OLD ? QS_NEW : null;
}

/** Keep noCompatMode from quoting YAML 1.1 base60 values. A check that is not the js-yaml dumper is refused. */
export function respectNoCompatModeForBase60(source: string): string | null {
  if (!source.includes("DEPRECATED_BASE60_SYNTAX")) return null;
  return source === YAML_OLD ? YAML_NEW : null;
}

/** Treat an unpaired quote as ordinary text. A check that is not the braces parser is refused. */
export function treatUnpairedQuotesAsText(source: string): string | null {
  if (!source.includes("CHAR_DOUBLE_QUOTE || value === CHAR_SINGLE_QUOTE || value === CHAR_BACKTICK")) return null;
  return source === BRACES_OLD ? BRACES_NEW : null;
}

export interface Batch36Input {
  root: string;
  output: string;
  sourcePattern?: string;
  nodePath: string;
  nodeModules?: string | null;
  testCommand: readonly string[];
  bwrap?: string;
}

function readLocal(dir: string, path: string): string | null {
  try {
    return readFileSync(join(dir, path), "utf8");
  } catch {
    return null;
  }
}

function filesOf(dir: string, pattern: string | undefined): string[] {
  const listed = practiceGit(dir, ["ls-files"]);
  if (!listed.ok) return [];
  return listed.out.split("\n").map((p) => p.trim()).filter((p) => /\.(?:tsx?|js)$/.test(p) && !p.endsWith(".d.ts") && (!pattern || new RegExp(pattern).test(p)));
}

/** Apply the one repair the failure can prove, then require the published test to pass in the sandbox. */
export function repairBatch36(input: Batch36Input): { diff: string; file: string } | null {
  if (!/Error|not equal|Expected|Invalid|fail|toEqual|toBe|AssertionError|TypeError|undefined|to equal|deeply equivalent|deepEqual|deep-equal|deepEqual|null|1:23|quote|%2e|%2E/i.test(input.output)) return null;
  const edits: { path: string; next: string; original: string }[] = [];
  for (const path of filesOf(input.root, input.sourcePattern)) {
    const original = readLocal(input.root, path);
    if (original === null) continue;
    const next = decodeDotKeysCaseInsensitively(original) ?? respectNoCompatModeForBase60(original) ?? treatUnpairedQuotesAsText(original);
    if (next && next !== original) edits.push({ path, next, original });
  }
  if (edits.length !== 1) return null;
  const edit = edits[0]!;
  try {
    writeFileSync(join(input.root, edit.path), edit.next);
    const again = runInPracticeSandbox(input.root, input.testCommand, 180_000, {
      capture: true, nodePath: input.nodePath, nodeModules: input.nodeModules, ...(input.bwrap ? { bwrap: input.bwrap } : {}),
    });
    if (again.unsafe || again.code !== 0) return null;
    const diff = practiceGit(input.root, ["diff", "--no-color", "--no-ext-diff", "--no-renames", "--", edit.path]);
    if (!diff.ok || !diff.out.trim()) return null;
    return { diff: diff.out, file: edit.path };
  } finally {
    writeFileSync(join(input.root, edit.path), edit.original);
  }
}
